/**
 * Apple Root CA - G3 (DER, base64). StoreKit 2 거래·App Store 서버 알림의 서명 체인은 이 루트로 끝난다.
 *
 * 출처: https://www.apple.com/certificateauthority/AppleRootCA-G3.cer (공개 인증서 — 비밀이 아니다)
 * SHA-256 지문: 63:34:3A:BF:B8:9A:6A:03:EB:B5:7E:9B:3F:5F:A7:BE:7C:4F:5C:75:6F:30:17:B3:A8:C4:88:C3:65:3E:91:79
 * 만료: 2039-04-30
 *
 * 파일이 아니라 상수로 두는 이유: 빌드(tsc)가 `.cer`를 `dist`로 옮기지 않는다 — 자산 복사 설정을 늘리는 대신
 * 코드에 싣는다. 값을 바꿀 일은 Apple이 루트를 교체할 때뿐이고, 그때는 지문을 위 출처와 대조한다.
 */
export const APPLE_ROOT_CA_G3_BASE64 =
  '';

export const APPLE_ROOT_CERTIFICATES: Buffer[] = [
  Buffer.from(APPLE_ROOT_CA_G3_BASE64, 'base64'),
];
